const placeIndex = new Map(places.map((item) => [item.id, item]));
const events: HistoryEvent[] = eventSeeds.map((seed, index, all) => {
  const currentRelations = new Set([...seed.organizationIds, ...seed.personIds, ...seed.technologyIds]);
  const previous = all
    .slice(0, index)
    .reverse()
    .find((candidate) =>
      [...candidate.organizationIds, ...candidate.personIds, ...candidate.technologyIds]
        .some((id) => currentRelations.has(id)),
    );
  const coordinates = placeIndex.get(seed.placeId);
  return {
    ...seed,
    relatedEventIds: previous ? [previous.id] : [],
    tags: [...new Set([seed.category, ...seed.organizationIds.map((id) => id.replace(/^o-/, "")), ...seed.technologyIds.map((id) => id.replace(/^t-/, ""))])],
    map: { x: coordinates?.x ?? 50, y: coordinates?.y ?? 50 },
  };
});

export const historyCatalog: HistoryCatalog = {
  schemaVersion: DATA_SCHEMA_VERSION,
  eras,
  places,
  organizations,
  people,
  technologies,
  sources,
  events,
};
